import{_ as t,o as a,c as d,a2 as o}from"./chunks/framework.DGu13UIe.js";const f=JSON.parse('{"title":"第 120 课 · 编辑与 Diff 预览（规划中）","description":"","frontmatter":{"editLink":"https://github.com/SyncLionPaw/bagent/edit/main/lessons/120-edit-diff/doc.md"},"headers":[],"relativePath":"chapters/120-edit-diff.md","filePath":"chapters/120-edit-diff.md"}'),i={name:"chapters/120-edit-diff.md"};function s(r,e,n,l,c,h){return a(),d("div",null,[...e[0]||(e[0]=[o(`<h1 id="第-120-课-·-编辑与-diff-预览-规划中" tabindex="-1">第 120 课 · 编辑与 Diff 预览（规划中） <a class="header-anchor" href="#第-120-课-·-编辑与-diff-预览-规划中" aria-label="Permalink to &quot;第 120 课 · 编辑与 Diff 预览（规划中）&quot;">​</a></h1><p><strong>状态：未实现</strong> · 路线图章节，先讲清要做成什么样</p><hr><h2 id="_0-这课解决什么" tabindex="-1">0. 这课解决什么 <a class="header-anchor" href="#_0-这课解决什么" aria-label="Permalink to &quot;0. 这课解决什么&quot;">​</a></h2><p><a href="/bagent/chapters/43-write-file.html">第 43 课</a> 已提供带审批的 <strong><code>write_file</code>（整文件覆盖，无 diff）</strong>。本课规划的是 <strong>先预览 diff、再 Accept 写盘</strong> 的产品级体验。</p><p>真正的 Code Agent（Cursor、Copilot 等）还要能 <strong>提案修改 → 红绿 diff 预览 → 用户 Accept 才写盘</strong>。<a href="/bagent/chapters/38-agent-product.html">第 38 课</a> 刻意把写盘留到后面；本课就是那条线的落点。</p><hr><h2 id="_1-整条链路-client-画-ui-agent-只出改法" tabindex="-1">1. 整条链路（Client 画 UI，Agent 只出改法） <a class="header-anchor" href="#_1-整条链路-client-画-ui-agent-只出改法" aria-label="Permalink to &quot;1. 整条链路（Client 画 UI，Agent 只出改法）&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>用户：把这个函数加上类型注解</span></span>
<span class="line"><span>  → Agent 调 search_replace / apply_patch（工具参数）</span></span>
<span class="line"><span>  → 插件算出「改后全文」（内存里，磁盘未动）</span></span>
<span class="line"><span>  → vscode.diff 或内联 decoration 展示红绿对比</span></span>
<span class="line"><span>  → 用户 Accept → WorkspaceEdit 写盘</span></span>
<span class="line"><span>  → ToolResult 回传给 Agent，继续下一轮</span></span></code></pre></div><p>和 <a href="/bagent/chapters/35-tool-approval.html">第 35 课</a> 审批的关系：</p><table tabindex="0"><thead><tr><th>阶段</th><th>读工具（现已实现）</th><th>写工具（本课）</th></tr></thead><tbody><tr><td>模型意图</td><td><code>read_file</code> / <code>grep</code></td><td><code>search_replace</code> / <code>apply_patch</code></td></tr><tr><td>用户确认</td><td>Webview ✓/✗</td><td><strong>先看 diff</strong>，再 Accept / Reject</td></tr><tr><td>副作用</td><td>无</td><td>Accept 后才 <code>applyEdit</code></td></tr></tbody></table><p><a href="/bagent/chapters/39-agent-client-protocol.html">第 39 课 ACP</a> 里说的「diff 在 IDE 画」就是这个分工：Agent 不抢编辑器，插件负责展示与落盘。</p><hr><h2 id="_2-计划里的工具形态" tabindex="-1">2. 计划里的工具形态 <a class="header-anchor" href="#_2-计划里的工具形态" aria-label="Permalink to &quot;2. 计划里的工具形态&quot;">​</a></h2><h3 id="search-replace-优先" tabindex="-1"><code>search_replace</code>（优先） <a class="header-anchor" href="#search-replace-优先" aria-label="Permalink to &quot;\`search_replace\`（优先）&quot;">​</a></h3><div class="language-json vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">json</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">{</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;path&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;/abs/path/to/file.ts&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;old_string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;function foo() {&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">,</span></span>
<span class="line"><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">  &quot;new_string&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;function foo(x: number) {&quot;</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><ul><li><code>old_string</code> 须在文件中 <strong>唯一匹配</strong>，否则返回错误让模型重试</li><li>执行函数 <strong>先不写盘</strong>，只返回 <code>{ path, oldContent, newContent }</code> 给插件</li></ul><h3 id="apply-patch-可选进阶" tabindex="-1"><code>apply_patch</code>（可选进阶） <a class="header-anchor" href="#apply-patch-可选进阶" aria-label="Permalink to &quot;\`apply_patch\`（可选进阶）&quot;">​</a></h3><p>Unified diff / patch 文本，适合多行、多 hunk 修改；Client 用同样方式算 <code>newContent</code> 再 diff。</p><h3 id="安全钩子-before" tabindex="-1">安全钩子（<code>before</code>） <a class="header-anchor" href="#安全钩子-before" aria-label="Permalink to &quot;安全钩子（\`before\`）&quot;">​</a></h3><ul><li>路径必须在 cwd 子树下（与 <code>grep</code> / <code>read_file</code> 一致）</li><li>默认禁止改 <code>.git</code>、<code>.env</code>、<code>node_modules</code></li><li>可限制单次 patch 行数 / 文件数</li></ul><hr><h2 id="_3-插件侧要做的事" tabindex="-1">3. 插件侧要做的事 <a class="header-anchor" href="#_3-插件侧要做的事" aria-label="Permalink to &quot;3. 插件侧要做的事&quot;">​</a></h2><p>在 <a href="/bagent/chapters/40-vscode-kernel-upgrade.html">第 40 课</a> 的 stdio + Webview 上扩展：</p><table tabindex="0"><thead><tr><th>能力</th><th>做法</th></tr></thead><tbody><tr><td>Diff 预览</td><td><code>vscode.diff</code> + <code>TextDocumentContentProvider</code>（<code>bagent:old</code> / <code>bagent:new</code> 虚拟 URI）</td></tr><tr><td>或内联高亮</td><td><code>TextEditorDecorationType</code> 标增删行</td></tr><tr><td>Accept</td><td><code>vscode.workspace.applyEdit(WorkspaceEdit)</code></td></tr><tr><td>事件（拟定）</td><td><code>EditPreview { path, hunks? }</code>，Webview 可显示「待确认 1 处修改」</td></tr><tr><td>拒绝</td><td>不落盘，<code>ToolAborted</code> 回内核</td></tr></tbody></table><p>Worker 里 <strong>不</strong> 直接 <code>fs.writeFile</code>；写盘权限留在 Extension Host，和「审批在 UI、内核只等 <code>approve</code>」同一思路。</p><hr><h2 id="_4-diff-怎么算" tabindex="-1">4. Diff 怎么算 <a class="header-anchor" href="#_4-diff-怎么算" aria-label="Permalink to &quot;4. Diff 怎么算&quot;">​</a></h2><ol><li><strong>旧文本</strong>：磁盘当前内容（或 <code>read_file</code> 缓存）</li><li><strong>新文本</strong>：在内存里应用 <code>search_replace</code> / patch</li><li><strong>对比</strong>：按行 LCS（Myers diff），库可用 <code>diff</code>（jsdiff）或 VS Code 内置能力</li><li><strong>展示</strong>：删除行红、新增行绿；用户 Accept 前文件 URI 不变</li></ol><hr><h2 id="_5-前置与相关课文" tabindex="-1">5. 前置与相关课文 <a class="header-anchor" href="#_5-前置与相关课文" aria-label="Permalink to &quot;5. 前置与相关课文&quot;">​</a></h2><p>建议读完再动手实现本课：</p><table tabindex="0"><thead><tr><th>课</th><th>为什么需要</th></tr></thead><tbody><tr><td><a href="/bagent/chapters/35-tool-approval.html">第 35 课</a></td><td><code>approve</code> 管线</td></tr><tr><td><a href="/bagent/chapters/36-tool-hooks.html">第 36 课</a></td><td><code>before</code> / <code>after</code> 钩子</td></tr><tr><td><a href="/bagent/chapters/29-agent-split.html">第 29 课</a></td><td>Client / Agent 分工</td></tr><tr><td><a href="/bagent/chapters/40-vscode-kernel-upgrade.html">第 40 课</a></td><td>spawn、事件、Webview</td></tr><tr><td><a href="/bagent/chapters/41-code-search.html">第 41 课</a></td><td>只读探索已齐，再上加写</td></tr></tbody></table><hr><h2 id="_6-本课动手清单-实现时对照" tabindex="-1">6. 本课动手清单（实现时对照） <a class="header-anchor" href="#_6-本课动手清单-实现时对照" aria-label="Permalink to &quot;6. 本课动手清单（实现时对照）&quot;">​</a></h2><ul><li>[ ] <code>search_replace</code> 工具 + <code>before</code> 路径校验</li><li>[ ] 工具执行返回「提案」，写盘移到插件 Accept</li><li>[ ] <code>EditPreview</code>（或复用 <code>ToolCallPending</code> + diff 页）</li><li>[ ] <code>vscode.diff</code> 并排预览</li><li>[ ] Accept / Reject 与 <code>approve</code> 打通</li><li>[ ] 课文示例：改插件里一行文案，F5 里走完整流程</li><li>[ ] 同步 ch40 <code>agent/</code> 与终端 ch36 内核</li></ul><hr><h2 id="_7-刻意仍不做" tabindex="-1">7. 刻意仍不做 <a class="header-anchor" href="#_7-刻意仍不做" aria-label="Permalink to &quot;7. 刻意仍不做&quot;">​</a></h2><ul><li>无限制 <code>run_shell</code></li><li>自动 Accept、无预览写盘</li><li>对标 Cursor 全量 multi-file refactor</li><li>MCP / RAG 全家桶（见 <a href="/bagent/chapters/38-agent-product.html">第 38 课</a>）</li></ul><hr><p><strong>当前</strong>：仓库尚无本课代码；第 42–119 课槽位留给 CLI TUI、内核抽包、更多只读工具等。本课编号 <strong>120</strong> 固定留给「编辑 + diff」。</p>`,41)])])}const g=t(i,[["render",s]]);export{f as __pageData,g as default};
